package net.nuggetmc.tplus.compat.bukkit.event.player;
import net.nuggetmc.tplus.compat.bukkit.event.*; import net.nuggetmc.tplus.compat.bukkit.entity.Player; import net.nuggetmc.tplus.compat.bukkit.block.Block; import net.nuggetmc.tplus.compat.bukkit.block.BlockFace; import net.nuggetmc.tplus.compat.bukkit.inventory.*; import net.nuggetmc.tplus.compat.bukkit.Material;
public class PlayerBucketEmptyEvent extends Event implements Cancellable { private final Player player;private final Block block,blockClicked;private final BlockFace face;private final Material bucket;private final ItemStack item;private final EquipmentSlot hand;private boolean cancelled;public PlayerBucketEmptyEvent(Player p,Block b,Block support,BlockFace f,Material bucket,ItemStack item,EquipmentSlot hand){player=p;block=b;blockClicked=support;face=f;this.bucket=bucket;this.item=item;this.hand=hand;}public Player getPlayer(){return player;}public Block getBlock(){return block;}public Block getBlockClicked(){return blockClicked;}public BlockFace getBlockFace(){return face;}public Material getBucket(){return bucket;}public ItemStack getItemStack(){return item;}public EquipmentSlot getHand(){return hand;}public boolean isCancelled(){return cancelled;}public void setCancelled(boolean v){cancelled=v;} }
